	/** Get appointments from Easy!Appointments, with a JetAppointments fallback. */
	private static function get_appointments( $date, $view ) {
		$from = $date; $to = $date;
		if ( 'weekly' === $view ) { $from = self::week_start( $date ); $to = wp_date( 'Y-m-d', strtotime( $from . ' +6 days' ) ); }
		if ( 'monthly' === $view ) { $from = self::jalali_month_start( $date ); $to = self::jalali_month_end( $date ); }
		if ( class_exists( 'HMN_CRM_EasyAppointments' ) && HMN_CRM_EasyAppointments::configured() ) {
			$remote = HMN_CRM_EasyAppointments::appointments( $from, $to );
			if ( is_array( $remote ) ) { return $remote; }
		}
		global $wpdb;
		$table = $wpdb->prefix . 'jet_appointments';
		if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $table ) ) !== $table ) {
			return array();
		}
		$columns = $wpdb->get_col( "DESCRIBE {$table}", 0 ); // Table name is WordPress-prefix derived.
		$date_column = in_array( 'appointment_date', $columns, true ) ? 'appointment_date' : ( in_array( 'date', $columns, true ) ? 'date' : '' );
		if ( ! $date_column ) { return array(); }
		$rows = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$table} WHERE {$date_column} BETWEEN %s AND %s ORDER BY {$date_column} ASC", $from, $to ), ARRAY_A );
		return is_array( $rows ) ? $rows : array();
	}

	private static function render_schedule( $view, $date, $appointments, $base ) {
		if ( 'daily' === $view ) { self::render_table( $appointments ); return; }
		$start = 'weekly' === $view ? self::week_start( $date ) : self::jalali_month_start( $date );
		$days = 'weekly' === $view ? 7 : (int) ( ( strtotime( self::jalali_month_end( $date ) ) - strtotime( $start ) ) / DAY_IN_SECONDS ) + 1;
		$by_date = array(); foreach ( $appointments as $appointment ) { $day = self::appointment_value( $appointment, array( 'appointment_date', 'date' ) ); if ( $day ) { $by_date[ substr( $day, 0, 10 ) ][] = $appointment; } }
		echo '<div class="hmn-board ' . esc_attr( $view ) . '">';
		if ( 'weekly' === $view ) { echo '<div style="grid-column:1/-1;display:grid;grid-template-columns:repeat(7,minmax(130px,1fr));gap:10px;text-align:center;color:#768198;font-size:12px;font-weight:700"><span>شنبه</span><span>یکشنبه</span><span>دوشنبه</span><span>سه‌شنبه</span><span>چهارشنبه</span><span>پنجشنبه</span><span>جمعه</span></div>'; }
		for ( $i = 0; $i < $days; $i++ ) { $day = wp_date( 'Y-m-d', strtotime( $start . " +{$i} days" ) ); $items = isset( $by_date[ $day ] ) ? $by_date[ $day ] : array(); echo '<a class="hmn-day-box" href="' . esc_url( add_query_arg( array( 'view' => 'daily', 'date' => $day ), $base ) ) . '"><strong>' . esc_html( self::jalali_date( $day, 'l j F' ) ) . '</strong><span>' . esc_html( count( $items ) ) . ' نوبت</span>'; foreach ( array_slice( $items, 0, 3 ) as $item ) { echo '<small>' . esc_html( self::appointment_value( $item, array( 'appointment_time', 'time', 'slot' ), '—' ) ) . ' · ' . esc_html( self::patient_name( $item ) ) . '</small>'; } echo '</a>'; }
		echo '</div>';
	}

	private static function render_table( $appointments ) {
		if ( empty( $appointments ) ) { echo '<div class="hmn-empty"><span>⌁</span><h3>برای این روز نوبتی ثبت نشده است</h3><p>با انتخاب یک روز دیگر از تقویم، برنامه همان روز نمایش داده می‌شود.</p></div>'; return; }
		echo '<div class="hmn-table-wrap"><table><thead><tr><th>ساعت</th><th>نام و نام خانوادگی</th><th>شماره</th><th>خدمت</th><th>شماره پرونده</th><th>عملیات</th></tr></thead><tbody>';
		foreach ( $appointments as $item ) { $id = absint( self::appointment_value( $item, array( 'id' ) ) ); $phone = self::appointment_value( $item, array( 'user_phone', 'phone', 'user_email' ), '—' ); $name = self::patient_name( $item ); echo '<tr><td>' . esc_html( self::appointment_value( $item, array( 'appointment_time', 'time', 'slot' ), '—' ) ) . '</td><td><strong>' . esc_html( $name ) . '</strong></td><td class="hmn-center" dir="ltr">' . esc_html( $phone ) . '</td><td>' . esc_html( self::appointment_value( $item, array( 'service_title', 'service', 'service_id' ), '—' ) ) . '</td><td class="hmn-center">' . esc_html( self::appointment_value( $item, array( 'case_number', 'file_number', 'id' ), '—' ) ) . '</td><td><div class="hmn-actions"><button type="button" class="hmn-action hmn-view" data-phone="' . esc_attr( $phone ) . '">مشاهده</button><button type="button" class="hmn-action hmn-move" data-id="' . esc_attr( $id ) . '" data-phone="' . esc_attr( $phone ) . '" data-name="' . esc_attr( $name ) . '">جابجایی</button><button type="button" class="hmn-action hmn-cancel" data-id="' . esc_attr( $id ) . '">کنسل</button></div></td></tr>'; }
		echo '</tbody></table></div><div class="hmn-history-modal" hidden><div class="hmn-history-card"><button type="button" class="hmn-history-close">×</button><h3>سابقه نوبت‌های مراجعه‌کننده</h3><div class="hmn-history-content"></div></div></div>';
		?><style>.hmn-center{text-align:center!important}.hmn-actions{display:flex;gap:6px}.hmn-cancel{background:#fff1f3;color:#b42318}.hmn-move{background:#eff8ff;color:#175cd3}.hmn-history-modal{position:fixed;inset:0;z-index:1001;background:rgba(16,24,40,.45);display:grid;place-items:center;padding:16px}.hmn-history-modal[hidden]{display:none}.hmn-history-card{position:relative;width:min(100%,560px);max-height:80vh;overflow:auto;border-radius:16px;background:#fff;padding:24px}.hmn-history-close{position:absolute;top:12px;left:12px;width:32px;height:32px;border:0;border-radius:50%;font-size:20px;cursor:pointer}.hmn-history-row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;padding:11px 0;border-bottom:1px solid #eaecf0}@media(max-width:640px){.hmn-actions{flex-wrap:wrap}.hmn-history-row{grid-template-columns:1fr}}</style><script>(function(){var ajax=<?php echo wp_json_encode( admin_url( 'admin-ajax.php' ) ); ?>,nonce=<?php echo wp_json_encode( wp_create_nonce( 'hmn_ea_operator_booking' ) ); ?>,modal=document.querySelector('.hmn-history-modal'),content=modal.querySelector('.hmn-history-content');function req(a,d){d.action=a;d.nonce=nonce;return fetch(ajax,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(d)}).then(r=>r.json()).then(r=>{if(!r.success)throw Error(r.data&&r.data.message||'خطا');return r.data})}document.addEventListener('click',function(e){var b=e.target.closest('.hmn-view,.hmn-cancel,.hmn-move');if(!b)return;if(b.classList.contains('hmn-view')){modal.hidden=false;content.textContent='در حال دریافت سابقه…';req('hmn_ea_customer_history',{phone:b.dataset.phone}).then(r=>{content.innerHTML=r.history.length?r.history.map(x=>'<div class="hmn-history-row"><span>'+x.date+'</span><span>'+x.time+' — '+x.service+'</span><span>'+x.status+'</span></div>').join(''):'سابقه نوبتی برای این مراجعه‌کننده ثبت نشده است.'}).catch(x=>content.textContent=x.message);return}if(b.classList.contains('hmn-cancel')){if(!confirm('نوبت لغو شود؟ پیامک لغو نیز ارسال می‌شود.'))return;req('hmn_ea_cancel_appointment',{appointment_id:b.dataset.id}).then(()=>location.reload()).catch(x=>alert(x.message));return}if(b.classList.contains('hmn-move')){var f=document.querySelector('.hmn-operator-booking .hmn-ea-form'),panel=document.querySelector('.hmn-operator-panel');if(!f||!panel)return;window.hmnRebook={id:b.dataset.id};var p=(b.dataset.name||'').trim().split(/\s+/);f.elements.first_name.value=p.shift()||'';f.elements.last_name.value=p.join(' ');f.elements.operator_phone.value=b.dataset.phone||'';f.elements.operator_phone.dispatchEvent(new Event('input',{bubbles:true}));panel.hidden=false}});modal.querySelector('.hmn-history-close').onclick=function(){modal.hidden=true};modal.onclick=function(e){if(e.target===modal)modal.hidden=true};var f=document.querySelector('.hmn-operator-booking .hmn-ea-form');if(f)new MutationObserver(function(){var m=f.querySelector('.hmn-ea-message').textContent;if(!window.hmnRebook||m.indexOf('نوبت با موفقیت ثبت شد')!==0)return;var old=window.hmnRebook;window.hmnRebook=null;req('hmn_ea_cancel_appointment',{appointment_id:old.id,silent:1}).then(()=>location.reload()).catch(x=>alert('نوبت جدید ثبت شد ولی لغو قبلی ناموفق بود: '+x.message))}).observe(f.querySelector('.hmn-ea-message'),{childList:true,subtree:true,characterData:true})})();</script><?php
